import { Mesh, PlaneGeometry, MeshBasicNodeMaterial, ClampToEdgeWrapping } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { scenePosition, assets, atlas } = config;
  const imageUrl = assets.imageUrl;

  // Load texture (assumed synchronous from cache)
  const texture = ctx.textureLoader.load(imageUrl);
  texture.wrapS = ClampToEdgeWrapping;
  texture.wrapT = ClampToEdgeWrapping;

  // Apply atlas region (source rect in pixels, top-left origin)
  const { sourceX, sourceY, sourceWidth, sourceHeight } = atlas[0]; // atlas 0
  const img = texture.image;
  const imgW = img ? img.width : 1;
  const imgH = img ? img.height : 1;

  const repeatX = sourceWidth / imgW;
  const repeatY = sourceHeight / imgH;
  const offsetX = sourceX / imgW;
  const offsetY = (imgH - sourceY - sourceHeight) / imgH; // flip Y for UV

  texture.repeat.set(repeatX, repeatY);
  texture.offset.set(offsetX, offsetY);

  // Plane geometry sized to source rect aspect ratio
  const aspect = sourceWidth / sourceHeight;
  const geometry = new PlaneGeometry(aspect, 1);

  const material = new MeshBasicNodeMaterial({
    map: texture,
  });

  const mesh = new Mesh(geometry, material);
  mesh.position.set(scenePosition.x, scenePosition.y, scenePosition.z);
  mesh.rotation.set(scenePosition.rx || 0, scenePosition.ry || 0, scenePosition.rz || 0);
  mesh.scale.set(scenePosition.sx || 1, scenePosition.sy || 1, scenePosition.sz || 1);

  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return mesh;
}
